import { defineComponent } from 'vue';

import { IAssetConfig } from '@game-studio/asset-manager';

import { inversifyContainer } from '../../inversify/container';
import { device } from '../../services/device';
import { queryStringParams } from '../../services/query-string';
import { IGameRulesContentItem } from '../../types';
import { Assets } from 'pixi.js';

export default defineComponent({
    name: 'GameRules',
    data() {
        return {
            isDesktop: device.type.isDesktop
        };
    },
    computed: {
        strings() {
            return inversifyContainer.strings;
        }
    },
    methods: {
        checkSkin(item: IGameRulesContentItem): boolean {
            const skinAssetList = inversifyContainer.skin.dataList as IAssetConfig;
            return item.skin !== undefined && item.skin !== skinAssetList.skin;
        },
        getJackpotImagePath(filename: string): string {
            const operator = inversifyContainer.operatorModel.name;
            const locale = queryStringParams.locale;

            const regionFolder = locale === 'en-gb' ? 'core' : `regional/${locale.split('-')[0]}`;

            return `./static/shared-jackpots-assets/${operator}/${regionFolder}/textures/${filename}`;
        },
        getImagePath(value: string): string {
            const filename = value.includes(':') ? value.split(':')[1] : value;

            if (value.includes('jackpot')) {
                return this.getJackpotImagePath(filename);
            }

            const fileKey = filename.replace(/\.[^.]*$/, '');

            return Assets.resolver.hasKey(fileKey)
                ? (Assets.resolver.resolveUrl(fileKey) as string)
                : '';
        }
    }
});
